// Returns the correct official finder-tool URL for a board + qualification level. Use this rather
// than hardcoding a board's URL elsewhere, so a future path change only needs updating here.
export function getPastPaperSourceUrl(board, level) {
  const src = PAST_PAPER_SOURCES[board]
  if (!src) return null
  if (board === 'CCEA') {
    return level === 'GCSE' ? src.pastPapersGCSE : src.pastPapersGCE
  }
  if (board === 'WJEC') {
    return src.eduqasPastPapers // Eduqas is the relevant brand for the vast majority of app users
  }
  return src.pastPapers
}


// `level` matters here as much as board/tier: PAPER_DATABASE keys A-Level papers with an
// '-Alevel-' infix (e.g. 'AQA-Mathematics-N/A-Alevel-P1') specifically so they can never collide
// with a same-numbered GCSE paper for the same board+subject (e.g. an untiered GCSE subject's
// 'AQA-Geography-N/A-P1'). Previously this function didn't take level at all, so it always built
// the GCSE-style key — meaning it could never find any A-Level paper (always returned null), and
// for untiered subjects that exist at both GCSE and A-Level, it would have silently handed back
// the GCSE paper's spec to an A-Level lookup the moment A-Level data was queried this way.
export function getPaperSpec(board, subject, tier, paper, level) {
  const t = tier && tier !== 'N/A' ? tier : 'N/A'
  if (level === 'A-Level') {
    return PAPER_DATABASE[`${board}-${subject}-N/A-Alevel-P${paper}`] || null
  }
  if (level === 'AS-Level') {
    return PAPER_DATABASE[`${board}-${subject}-N/A-ASLevel-P${paper}`] || null
  }
  const key = `${board}-${subject}-${t}-P${paper}`
  const alt = `${board}-${subject}-N/A-P${paper}`
  return PAPER_DATABASE[key] || PAPER_DATABASE[alt] || null
}

// Was a third, separately-drifting copy of this list (see subjects.js's TIERED_SUBJECTS, which is
// now the single source of truth — imported below).
const TIERED = TIERED_SUBJECTS

function normSubj(subject) {
  return subject
    .replace(/ A$/, '').replace(/ B$/, '')
    .replace(/ \(Advancing Biology\)/, '')
    .replace(/ \(Salters\)/, '')
    .replace(/ A \(/, ' (')
    .replace(/\s+A-Level$/, '')
    .trim()
}

export function getBoundaries(board, subject, tier, year, level) {
  const norm = normSubj(subject)
  const isTieredSubj = TIERED.includes(subject) || TIERED.includes(norm)
  const isALevel = level === 'A-Level'
  const isASLevel = level === 'AS-Level'

  function lookupIn(yearData) {
    if (!yearData) return null
    if (isALevel) {
      return yearData[`${board}-${subject}-N/A-Alevel`] || yearData[`${board}-${norm}-N/A-Alevel`] || null
    }
    if (isASLevel) {
      return yearData[`${board}-${subject}-N/A-ASLevel`] || yearData[`${board}-${norm}-N/A-ASLevel`] || null
    }
    if (isTieredSubj && tier && tier !== 'N/A') {
      return yearData[`${board}-${subject}-${tier}`]
          || yearData[`${board}-${norm}-${tier}`]
          || yearData[`${board}-${subject}`]
          || yearData[`${board}-${norm}`]
          || null
    }
    return yearData[`${board}-${subject}`] || yearData[`${board}-${norm}`] || null
  }

  // 2026 results started landing 13 Aug (A-Level/AS) and 20 Aug (GCSE) 2026. Try real 2026 data
  // first for this specific combo before falling back, instead of the old blanket redirect that
  // would have silently ignored real 2026 data forever once it existed.
  if (year === 2026 && GRADE_BOUNDARIES[2026]) {
    const real2026 = lookupIn(GRADE_BOUNDARIES[2026])
    if (real2026) return real2026
  }
  const lookupYear = (!GRADE_BOUNDARIES[year] || year === 2026) ? 2025 : year
  const yearData = GRADE_BOUNDARIES[lookupYear] || GRADE_BOUNDARIES[2024]
  return lookupIn(yearData)
}

export function getBoundariesForPaper(board, subject, tier, year, paper, level) {
  // Mirrors the 2026-first-then-fallback logic in getBoundaries() above.
  if (year === 2026 && GRADE_BOUNDARIES[2026] && level !== 'A-Level' && level !== 'AS-Level') {
    const paperKey2026 = `${board}-${subject}-P${paper}`
    if (GRADE_BOUNDARIES[2026][paperKey2026]) return GRADE_BOUNDARIES[2026][paperKey2026]
  }
  const lookupYear = (!GRADE_BOUNDARIES[year] || year === 2026) ? 2025 : year
  const yearData = GRADE_BOUNDARIES[lookupYear] || GRADE_BOUNDARIES[2024]
  // A handful of untiered GCSE subjects (AQA English Literature, AQA Geography) have a different
  // maxMarks/boundary set per paper, so they're keyed as `${board}-${subject}-P${paper}` rather
  // than at subject level. That key was never given a level suffix because it only ever existed
  // for GCSE — so this lookup must stay GCSE-only. Without the level guard, an A-Level or
  // AS-Level paper for a same-named subject (e.g. Geography) could silently match a GCSE paper's
  // boundaries the moment their paper numbers lined up.
  if (yearData && level !== 'A-Level' && level !== 'AS-Level') {
    const paperKey = `${board}-${subject}-P${paper}`
    if (yearData[paperKey]) return yearData[paperKey]
  }
  return getBoundaries(board, subject, tier, year, level)
}

export function calculateGradeFromBoundaries(score, boundaryData) {
  if (!boundaryData) return null
  const { boundaries, grades } = boundaryData
  const gradeLabels = grades || ['9','8','7','6','5','4','3','2','1']
  for (let i = 0; i < boundaries.length; i++) {
    if (boundaries[i] !== null && score >= boundaries[i]) return gradeLabels[i]
  }
  return 'U'
}

export function getBoundariesWithPercentages(board, subject, tier, year, paper, level) {
  const data = paper
    ? getBoundariesForPaper(board, subject, tier, year, paper, level)
    : getBoundaries(board, subject, tier, year, level)
  if (!data) return null
  const gradeLabels = data.grades || ['9','8','7','6','5','4','3','2','1']
  return {
    ...data,
    withPercentages: data.boundaries.map((b,i) => ({
      grade:      gradeLabels[i],
      marks:      b,
      percentage: b !== null ? Math.round((b / data.maxMarks)*100) : null,
      estimated:  !!(data.note && data.note.includes('~')),
    })).filter(x => x.marks !== null)
  }
}

export const AVAILABLE_YEARS = [2026, 2025, 2024, 2023, 2022, 2021, 2020, 2019]
// Note: 2026 grade boundaries will be published by exam boards in August 2026.
// Until then, logging a 2026 paper will calculate grade using 2025 boundaries as an estimate.
